import '../../../../core/result/app_result.dart'; import '../../domain/entities/tourist_destination.dart'; import '../../domain/repositories/explore_iraq_repository.dart'; import '../datasources/mock_destinations.dart';
class MockExploreRepository implements ExploreIraqRepository { @override Stream<List<TouristDestination>> observeDestinations()=>Stream.value(MockDestinations.data); @override Stream<List<TouristDestination>> observeFeaturedDestinations()=>Stream.value(MockDestinations.data.where((x)=>x.isFeatured).toList()); @override Stream<List<TouristDestination>> observePopularDestinations()=>Stream.value(MockDestinations.data.where((x)=>x.isPopular).toList()); @override Stream<List<TouristDestination>> observeDestinationsByProvince(String id)=>Stream.value(MockDestinations.data.where((x)=>x.provinceId==id).toList()); @override Future<AppResult<TouristDestination?>> getDestinationById(String id) async { for(final item in MockDestinations.data){if(item.id==id)return AppSuccess(item);} return const AppSuccess(null); } }
